     8	#include <open62541/plugin/log_stdout.h>
     9	#include <open62541/server_config_default.h>
    10	#include <open62541/types.h>
    11	
    12	#include "ua_server_internal.h"
    13	#include "testing_networklayers.h"
    14	
    15	#define RECEIVE_BUFFER_SIZE 65535
    16	
    17	/*
    18	** Main entry point.  The fuzzer invokes this function with each
    19	** fuzzed input.
    20	*/
    21	extern "C" int
    22	LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
    23	    if(size <= 4)
    24	        return 0;
    25	
    26	    /* less debug output */
    27	    UA_ServerConfig initialConfig;
    28	    memset(&initialConfig, 0, sizeof(UA_ServerConfig));
    29	    UA_StatusCode retval = UA_ServerConfig_setDefault(&initialConfig);
    30	    initialConfig.allowEmptyVariables = UA_RULEHANDLING_ACCEPT;
    31	    if(retval != UA_STATUSCODE_GOOD) {
    32	        UA_ServerConfig_clean(&initialConfig);
    33	        UA_LOG_ERROR(UA_Log_Stdout, UA_LOGCATEGORY_SERVER,
    34	                     "Could not generate the server config");
    35	        return 0;
    36	    }
    37	
    38	    UA_Server *server = UA_Server_newWithConfig(&initialConfig);
    39	    if(!server) {
    40	        UA_LOG_ERROR(UA_Log_Stdout, UA_LOGCATEGORY_SERVER,
    41	                     "Could not create server instance using UA_Server_new");
    42	        return 0;
    43	    }
    44	
    45	    // we need to copy the message because it will be freed in the processing function
    46	    UA_ByteString msg = UA_BYTESTRING_NULL;
    47	    retval = UA_ByteString_allocBuffer(&msg, size);
    48	    if(retval != UA_STATUSCODE_GOOD) {
    49	        UA_Server_delete(server);
    50	        UA_LOG_ERROR(UA_Log_Stdout, UA_LOGCATEGORY_SERVER,
    51	                     "Could not allocate message buffer");
    52	        return 0;
    53	    }
    54	    memcpy(msg.data, data, size);
    55	
    56	    /* Get the binary server components */
    57	    UA_String binStr = UA_STRING((char*)(uintptr_t)"binary");
    58	    UA_Driver *bpm = NULL;
    59	    for(UA_Driver *drv = server->drivers; drv; drv = drv->next) {
    60	        if(UA_String_equal(&binStr, &drv->name))
    61	            bpm = drv;
    62	    }
    63	    UA_assert(bpm != NULL);
    64	
    65	    void *ctx = NULL;
    66	    UA_ConnectionManager *cm = TestConnectionManager_new("tcp", NULL);
    67	    serverNetworkCallback(cm, 0, bpm,
    68	                          &ctx, UA_CONNECTIONSTATE_ESTABLISHED,
    69	                          &UA_KEYVALUEMAP_NULL, msg);
    70	    cm->eventSource.free(&cm->eventSource);
    71	
    72	    // if we got an invalid chunk, the message is not deleted, so delete it here
    73	    UA_ByteString_clear(&msg);
    74	    UA_Server_delete(server);
    75	    return 0;
    76	}
